#include "ode/native_ode.hpp"
#include "ode/advanced_ode_native.hpp"
#include "native_functions/native_callback.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <filesystem>
#include <iostream>
#include <numeric>
#include <stdexcept>
using namespace penta;
namespace {
int checks=0;
void require(bool okay,const std::string& message){++checks;if(!okay)throw std::runtime_error(message);}
void near(double a,double b,double tolerance,const std::string& message){require(std::abs(a-b)<=tolerance*(1+std::abs(b)),message+": "+std::to_string(a)+" vs "+std::to_string(b));}
template<class F>void fails(F callback,const std::string& code){try{callback();}catch(const ode::OdeError& error){require(error.code==code,"Expected "+code+", got "+error.code+": "+error.what());return;}throw std::runtime_error("Expected failure "+code);}
language::OdeDefinition definition(const std::string& source){const auto result=language::analyse(source);if(!result.ok()){std::string errors;for(const auto& error:result.diagnostics)errors+=error.code+": "+error.message+"\n";throw std::runtime_error(errors);}return *result.program.statements[0].ode;}
void references(const ode::NativeOptions& native){
    const auto decay=definition("ode decay(t,real y;real rate){y'=-rate*y;}");
    ode::SolveOptions options;options.t1=2;options.sampleStep=.5;options.rtol=1e-10;options.atol=1e-12;
    std::string key;
    for(auto method:{ode::Method::Bdf,ode::Method::Adams,ode::Method::Erk,ode::Method::Esdirk}){
        options.method=method;auto solution=ode::solve(decay,1,{2},{.7},options,native);require(solution->times.size()==5,"Coarse stored grid retained");require(solution->denseSegments.size()>5,"Native steps retain independent dense polynomials");near(ode::denseEvaluate(*solution,.371)[0],2*std::exp(-.7*.371),5e-8,"Dense native interpolation independent of sample_step");if(key.empty())key=solution->stats.key;else require(solution->stats.key==key&&solution->stats.cacheHit,"Methods and output options reuse structure");
        auto backward=options;backward.t0=2;backward.t1=0;auto reverse=ode::solve(decay,1,{2*std::exp(-1.4)},{.7},backward,native);require(reverse->times.front()==2&&reverse->times.back()==0,"Backward endpoints");near(reverse->values.back(),2,1e-7,"Backward exponential");near(ode::denseEvaluate(*reverse,.371)[0],2*std::exp(-.7*.371),1e-7,"Backward dense interpolation");
        auto events=options;events.eventCount=1;events.eventDirections={-1};events.eventTerminal={1};events.eventFunction=[](double,const double* y,double* g){g[0]=y[0]-1;};auto stopped=ode::solve(decay,1,{2},{.7},events,native);require(stopped->eventTimes.size()==1&&stopped->stats.terminalEvent,"Terminal event is stored");near(stopped->eventTimes[0],std::log(2)/.7,1e-8,"Localized native event time");near(stopped->values.back(),1,1e-9,"Terminal event state");require(stopped->eventDirections[0]==-1,"Forward event direction");
        auto reverseEvents=events;reverseEvents.t0=2;reverseEvents.t1=0;auto stoppedReverse=ode::solve(decay,1,{2*std::exp(-1.4)},{.7},reverseEvents,native);require(stoppedReverse->eventTimes.size()==1&&stoppedReverse->eventDirections[0]==-1,"Backward event direction uses physical increasing time");near(stoppedReverse->eventTimes[0],std::log(2)/.7,2e-8,"Backward event localization");
    }
    const auto oscillator=definition("ode crossings(t,real x,real y){x'=y;y'=-x;}");auto eventOptions=options;eventOptions.t1=7;eventOptions.eventCount=1;eventOptions.eventDirections={0};eventOptions.eventTerminal={0};eventOptions.eventFunction=[](double,const double* y,double* g){g[0]=y[0];};auto crossed=ode::solve(oscillator,1,{1,0},{},eventOptions,native);require(crossed->eventTimes.size()==2&&!crossed->stats.terminalEvent,"Nonterminal events preserve the full trajectory");near(crossed->eventTimes[0],std::acos(-1.0)/2,2e-8,"First nonterminal crossing");near(crossed->eventTimes[1],3*std::acos(-1.0)/2,2e-8,"Second nonterminal crossing");require(crossed->eventDirections==std::vector<int>({-1,1}),"Crossing directions retained separately");
    options.method=ode::Method::Bdf;options.outputTimes={0,.13,.47,1.23,2};auto sampled=ode::solve(decay,1,{2},{.7},options,native);require(sampled->times==options.outputTimes,"Arbitrary observation times are exact native outputs");for(std::size_t i=0;i<sampled->times.size();++i)near(sampled->values[i],2*std::exp(-.7*sampled->times[i]),2e-8,"Arbitrary sample reference");
    auto mass=options;mass.massMatrix={2};auto m=ode::solve(decay,1,{2},{.7},mass,native);near(m->values.back(),2*std::exp(-.7),2e-8,"Constant mass matrix");mass.massMatrix={0};fails([&]{(void)ode::solve(decay,1,{2},{.7},mass,native);},"O1001");
    auto limited=options;limited.maxSteps=1;fails([&]{(void)ode::solve(decay,1,{2},{.7},limited,native);},"O1006");limited=options;limited.maxDenseCoordinates=1;fails([&]{(void)ode::solve(decay,1,{2},{.7},limited,native);},"O1006");
    limited=options;limited.denseOutput=false;auto old=ode::solve(decay,1,{2},{.7},limited,native);require(old->denseSegments.empty(),"Dense storage can be disabled explicitly");fails([&]{(void)ode::denseEvaluate(*old,.1);},"O1011");
}
void sensitivitiesAndAdjoints(const ode::NativeOptions& native){
    const auto model=definition("ode sens(t,real y;real rate){y'=rate*y;}");auto rhs=ode::rhsFunction(model);native_functions::Options compiled;compiled.build=native;compiled.build.cacheDirectory=native.cacheDirectory/"callbacks";native_functions::Callback callback(rhs,compiled);
    ode::SolveOptions options;options.t1=1.2;options.sampleStep=.2;options.rtol=1e-10;options.atol=1e-12;options.sensitivityParameters={0,-1};options.sensitivityInitial={0,1};options.parameterJacobian=[&](double t,const double* state,double* out){native_functions::DerivativeRequest request;request.active={1};const auto result=callback.evaluate(1,{state[0],.4,t},request);out[0]=result.jacobian[0];};
    for(auto method:{ode::Method::Bdf,ode::Method::Adams})for(const auto* sensitivityMethod:{"simultaneous","staggered"}){options.method=method;options.sensitivityMethod=sensitivityMethod;auto result=ode::solve(model,1,{2},{.4},options,native);require(result->sensitivityCount==2&&result->stats.sensitivityRhsEvaluations>0,"CVODES integrates selected directions");for(std::size_t sample=0;sample<result->times.size();++sample){const auto t=result->times[sample];near(result->sensitivities[sample*2],2*t*std::exp(.4*t),2e-7,"Integrated parameter derivative");near(result->sensitivities[sample*2+1],std::exp(.4*t),2e-7,"Integrated initial-state derivative");}}
    options.sensitivityParameters.clear();options.sensitivityInitial.clear();for(auto method:{ode::Method::Bdf,ode::Method::Adams}){options.method=method;auto result=ode::solveAdjoint(model,1,{2},{.4},[](double,const double* y,const double* p,double* gy,double* gp){gy[0]=y[0];gp[0]=3;return .5*y[0]*y[0]+3*p[0];},options,native);const double y=2*std::exp(.4*options.t1);near(result.objective,.5*y*y+1.2,5e-8,"Terminal objective reference");near(result.parameterGradient[0],y*y*options.t1+3,2e-6,"Checkpointed adjoint parameter gradient incl direct term");near(result.initialGradient[0],y*std::exp(.4*options.t1),2e-6,"Checkpointed adjoint initial gradient");require(result.backwardSteps>0,"Adjoint backward integration ran");}
    auto checkpointed=options;checkpointed.maximumStep=.005;checkpointed.t1=2;auto replayed=ode::solveAdjoint(model,1,{2},{.4},[](double,const double* y,const double*,double* gy,double* gp){gy[0]=y[0];gp[0]=0;return .5*y[0]*y[0];},checkpointed,native);require(replayed.checkpoints>=3,"Adjoint traverses multiple stored checkpoints");near(replayed.parameterGradient[0],8*std::exp(1.6),3e-6,"Checkpoint replay parameter gradient");near(replayed.initialGradient[0],2*std::exp(1.6),3e-6,"Checkpoint replay initial gradient");
    auto backward=options;backward.t0=1;backward.t1=0;backward.sensitivityParameters={0,-1};backward.sensitivityInitial={0,1};auto reverse=ode::solve(model,1,{2},{.4},backward,native);near(reverse->sensitivities[reverse->sensitivities.size()-2],-2*std::exp(-.4),2e-7,"Backward parameter sensitivity");near(reverse->sensitivities.back(),std::exp(-.4),2e-7,"Backward initial-state sensitivity");backward.sensitivityParameters.clear();backward.sensitivityInitial.clear();auto reverseAdjoint=ode::solveAdjoint(model,1,{2},{.4},[](double,const double* y,const double* p,double* gy,double* gp){gy[0]=y[0];gp[0]=3;return .5*y[0]*y[0]+3*p[0];},backward,native);near(reverseAdjoint.parameterGradient[0],3-4*std::exp(-.8),2e-6,"Reverse-interval adjoint parameter gradient");
    // A real-coordinate tangent basis can be normalized between solves. Preserve
    // the R factors explicitly; no Lyapunov estimator is inferred by this test.
    const auto tangent=definition("ode tangent(t,real x,real y){x'=y;y'=-x;}");for(auto method:{ode::Method::Bdf,ode::Method::Adams}){ode::SolveOptions t;t.t1=.7;t.sampleStep=.35;t.rtol=1e-10;t.atol=1e-12;t.method=method;t.sensitivityParameters={-1,-1};t.sensitivityInitial={1,0,0,1};auto first=ode::solve(tangent,1,{1,0},{},t,native);const auto offset=first->sensitivities.size()-4;double q00=first->sensitivities[offset],q10=first->sensitivities[offset+1],q01=first->sensitivities[offset+2],q11=first->sensitivities[offset+3];const double r00=std::hypot(q00,q10);q00/=r00;q10/=r00;const double r01=q00*q01+q10*q11;q01-=q00*r01;q11-=q10*r01;const double r11=std::hypot(q01,q11);q01/=r11;q11/=r11;t.t0=.7;t.t1=1.4;t.sensitivityInitial={q00,q10,q01,q11};auto restarted=ode::solve(tangent,1,{first->values[first->values.size()-2],first->values.back()},{},t,native);t.t0=0;t.sensitivityInitial={1,0,0,1};auto whole=ode::solve(tangent,1,{1,0},{},t,native);const auto k=restarted->sensitivities.size()-4,w=whole->sensitivities.size()-4;for(std::size_t row=0;row<2;++row){near(restarted->sensitivities[k+row]*r00,whole->sensitivities[w+row],5e-7,"Restart/reorthogonalized first tangent column");near(restarted->sensitivities[k+row]*r01+restarted->sensitivities[k+2+row]*r11,whole->sensitivities[w+2+row],5e-7,"Restart/reorthogonalized second tangent column");}}
    const auto pent=definition("ode pentmodel(t,pentarnion p;pentarnion a){p'=a*p;}");auto pentRhs=ode::rhsFunction(pent);native_functions::Callback pentCallback(pentRhs,compiled);ode::SolveOptions p;p.t1=.25;p.sampleStep=.1;p.method=ode::Method::Bdf;p.rtol=1e-10;p.atol=1e-12;p.sensitivityParameters={0,1,2,3,4};const std::vector<double> a{.1,.2,0,0,0},initial{1,.1,-.1,.2,.05};p.parameterJacobian=[&](double t,const double* y,double* out){std::vector<double> input(y,y+5);input.insert(input.end(),a.begin(),a.end());input.push_back(t);native_functions::DerivativeRequest request;request.active={5,6,7,8,9};const auto result=pentCallback.evaluate(1,input,request);std::copy(result.jacobian.begin(),result.jacobian.end(),out);};auto result=ode::solve(pent,1,initial,a,p,native);p.sensitivityParameters.clear();p.parameterJacobian={};const double epsilon=1e-5;for(std::size_t parameter=0;parameter<5;++parameter){auto plus=a,minus=a;plus[parameter]+=epsilon;minus[parameter]-=epsilon;auto left=ode::solve(pent,1,initial,plus,p,native),right=ode::solve(pent,1,initial,minus,p,native);for(std::size_t c=0;c<5;++c)near(result->sensitivities[(result->times.size()-1)*25+parameter*5+c],(left->values[left->values.size()-5+c]-right->values[right->values.size()-5+c])/(2*epsilon),2e-5,"Five-coordinate Pentarnion parameter sensitivity vs independent solves");}
}
}
int main(){try{ode::NativeOptions native;native.cacheDirectory=std::filesystem::temp_directory_path()/("penta-advanced-ode-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));native.cancellation=std::make_shared<std::atomic_bool>(false);references(native);sensitivitiesAndAdjoints(native);native.cancellation->store(true);const auto model=definition("ode cancel(t,real x){x'=-x;}");fails([&]{(void)ode::solve(model,1,{1},{},{},native);},"O1004");std::cout<<checks<<" advanced native ODE checks, 0 failures\n";return 0;}catch(const std::exception& error){std::cerr<<"FAIL after "<<checks<<" checks: "<<error.what()<<'\n';return 1;}}

